import{_ as o,a0 as r,w as l,s as p,I as i,x as s,a1 as t,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"arm64 服务器中的 Debian armhf 虚拟机 | LCTT x X-CMD","titleTemplate":false,"description":"arm64 服务器中的 Debian armhf 虚拟机 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"arm64 服务器中的 Debian armhf 虚拟机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"arm64 服务器中的 Debian armhf 虚拟机 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170620 Debian armhf VM on arm64 server","title":"arm64 服务器中的 Debian armhf 虚拟机","tag":"201707","desc":""},"relativePath":"201707/20170620 Debian armhf VM on arm64 server.md","filePath":"[post].md"}'),m={name:"201707/20170620 Debian armhf VM on arm64 server.md"};function b(u,n,f,g,v,k){const a=r("Link");return l(),p("div",null,[n[31]||(n[31]=i("h1",{id:"arm64-服务器中的-debian-armhf-虚拟机",tabindex:"-1"},[s("arm64 服务器中的 Debian armhf 虚拟机 "),i("a",{class:"header-anchor",href:"#arm64-服务器中的-debian-armhf-虚拟机","aria-label":"Permalink to “arm64 服务器中的 Debian armhf 虚拟机”"},"​")],-1)),i("p",null,[n[2]||(n[2]=s("在 Collabora 公司，我们所做的许多工作之一就是为客户构建包括 32 位和 64 位 ARM 系统在内的各种架构的 ",-1)),t(a,{href:"https://debian.org/"},{default:e(()=>[...n[0]||(n[0]=[s("Debian",-1)])]),_:1}),n[3]||(n[3]=s(" 衍生版。就像 Debian 做的那样，我们的 ",-1)),t(a,{href:"http://openbuildservice.org/"},{default:e(()=>[...n[1]||(n[1]=[s("OBS",-1)])]),_:1}),n[4]||(n[4]=s(" 系统建立在原生系统而不是仿真器上。",-1))]),i("p",null,[n[6]||(n[6]=s("幸运的是随着几年前 ARM 服务器系统的出现，为这些系统原生构建不再像以前那么痛苦了。对于 32 位的 ARM，我们一直依赖 ",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Calxeda"},{default:e(()=>[...n[5]||(n[5]=[s("Calxeda",-1)])]),_:1}),n[7]||(n[7]=s(" 刀片服务器，然而不幸的是 Calxeda 在不久前淘汰，硬件开始显露其年龄（尽管幸运的是 Debian Stretch 还支持它，因此至少软件还是新的）。",-1))]),n[32]||(n[32]=i("p",null,"在 64 位 ARM 方面，我们运行在基于 Gigabyte MP30-AR1 的服务器上，该服务器可以运行 32 位的 ARM 代码（与之相反，比如基于 ThunderX 的服务器只能运行 64 位代码）。像这样在它们之上运行 armhf 虚拟机作为从构建服务器（build slaves）似乎是一个很好的选择，但是设置起来可能会需要更多东西的介入。",-1)),n[33]||(n[33]=i("p",null,"第一个陷阱是 Debian 中没有标准的 bootloader 或者 boot 固件来启动 qemu 仿真的 “virt” 设备（我不想使用真实机器的仿真）。这也意味着在启动时客户机内没有任何东西会加载内核，也不会从客户机网络引导，这意味着需要直接的内核引导。",-1)),i("p",null,[n[9]||(n[9]=s("第二个陷阱是当前的 Debian Stretch 的 armhf 内核并不支持 qemu 虚拟机所提供的通用 PCI 主机控制器，这意味着客户机中不会出现存储器和网络。希望这会被尽快解决（",-1)),t(a,{href:"https://bugs.debian.org/cgi-bin/bugreport.cgi?bug=864726"},{default:e(()=>[...n[8]||(n[8]=[s("Debian bug 864726",-1)])]),_:1}),n[10]||(n[10]=s("），并出现在 Stretch 更新中，那在之前需要使用 bug 报告中附带的补丁的自定义内核，但在这篇文章中我不想进一步说。",-1))]),i("p",null,[n[12]||(n[12]=s("高兴的假设我们有一个可用的内核，剩下的挑战是很好地管理直接内核加载。或者更具体地说，如何确保主机启动客户机通过标准 apt 工具安装的内核，而不必在客户机/主机之间复制内核，这本质上归结于客户机将 ",-1)),n[13]||(n[13]=i("code",null,"/boot",-1)),n[14]||(n[14]=s(" 暴露给主机。我们选择的方案是使用 qemu 的 9pfs 支持来从主机共享一个文件夹，并将其用作客户机的 ",-1)),n[15]||(n[15]=i("code",null,"/boot",-1)),n[16]||(n[16]=s("。对于 9p 文件夹，似乎需要 “mapped” 安全模式，因为 “none” 模式对 dpkg 有问题（[Debian bug 864718] ",-1)),t(a,{href:"https://bugs.debian.org/cgi-bin/bugreport.cgi?bug=864718"},{default:e(()=>[...n[11]||(n[11]=[s("5",-1)])]),_:1}),n[17]||(n[17]=s("）。",-1))]),n[34]||(n[34]=d(`<p>由于我们使用 libvirt 作为我们的虚拟机管理器，剩下的事情就是如何将它们组合到一起。</p><p>第一步是安装系统，基本和平常一样。可以直接引导进入由普通的 Stretch armhf netboot 安装程序提供的 <code>vmlinuz</code> 和 <code>initrd.gz</code>（下载到如 <code>/tmp</code> 中）。 设置整体来说很直接，会有一些小的调整：</p><ul><li><code>/srv/armhf-vm-boot</code> 设置为 9p 共享文件夹（这个应该存在，并且由 libvirt-qemu 拥有），这之后会被用于共享 <code>/boot</code>。</li><li>内核参数中在 <code>root=</code> 后面加上 VM 中的 root 分区，根据你的情况调整。</li><li>镜像文件使用 virtio 总线，这似乎不是默认的。</li></ul><p>除了这些调整，最后的示例命令与 virt-install 手册页中的相似。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>virt-install --name armhf-vm --arch armv7l --memory 512 \\</span></span>
<span class="line"><span>  --disk /srv/armhf-vm.img,bus=virtio</span></span>
<span class="line"><span>  --filesystem /srv/armhf-vm-boot,virtio-boot,mode=mapped \\</span></span>
<span class="line"><span>  --boot=kernel=/tmp/vmlinuz,initrd=/tmp/initrd.gz,kernel_args=&quot;console=ttyAMA0,root=/dev/vda1&quot;</span></span></code></pre></div><p>按照通常的方式运行安装。到最后安装程序可能会提示它不知道如何安装引导程序，这个没什么问题。只要在结束安装和重启之前，切换到 shell 并以某种方式将目标系统中的 <code>/boot/vmlinuz</code> 和 <code>/boot/initrd.img</code> 复制到主机中（比如 chroot 进入 <code>/target</code> 并在已安装的系统中使用 scp）。 这是必需的，因为安装程序不支持 9p，但是要启动系统，需要 initramfs 以及能够挂载根文件系统的模块，这由已安装的 initramfs 提供。这些完成后，安装就可以完成了。</p><p>接下来，引导已安装的系统。调整 libvirt 配置（比如使用 virsh 编辑并调整 xml）来使用从安装程序复制过来的内核以及 initramfs，而不只是使用它提供的。再次启动虚拟机，它应该就能愉快地进入安装的 Debian 系统中了。</p><p>要在客户机这一侧完成，<code>/boot</code> 应该移动到共享的 9pfs 中，<code>/boot</code> 的新 fstab 条目看上去应该这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>virtio-boot /boot  9p trans=virtio,version=9p2000.L,x-systemd.automount 0 0</span></span></code></pre></div><p>有了这一步，这只是将 <code>/boot</code> 中的文件混到新的文件系统里面，并且客户机完事了（确保 <code>vmlinuz</code>/<code>initrd.img</code> 保持符号链接）。内核可以如常升级，并对主机可见。</p><p>这时对于主机端，有另外一个问题需要跨过，由于客户机使用 9p 映射安全模式，客户机的符号链接对主机而言将是普通的包含链接目标的文件。为了解决这个问题，我们在客户机启动前使用 libvirt qemu 的 hook 支持来设置合适的符号链接。作为一个例子，下面是我们最终使用的脚本（<code>/etc/libvirt/hooks/qemu</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm=$1</span></span>
<span class="line"><span>action=$2</span></span>
<span class="line"><span>bootdir=/srv/\${vm}-boot</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ \${action} != &quot;prepare&quot; ] ; then</span></span>
<span class="line"><span>  exit 0</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ ! -d \${bootdir} ] ; then</span></span>
<span class="line"><span>  exit 0</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ln -sf $(basename $(cat \${bootdir}/vmlinuz))  \${bootdir}/virtio-vmlinuz</span></span>
<span class="line"><span>ln -sf $(basename $(cat \${bootdir}/initrd.img))  \${bootdir}/virtio-initrd.img</span></span></code></pre></div><p>有了这个，我们可以简单地定义 libvirt 使用 <code>/srv/\${vm}-boot/virtio-{vmlinuz,initrd.img}</code> 作为机器的内核 / <code>initramfs</code>，并且当 VM 启动时，它会自动获取客户机安装的最新内核 / <code>initramfs</code>。</p><p>只有最后一个边缘情况了，当从 VM libvirt 重启会让 qemu 处理它而不是重启 qemu。如果这不幸发生的话，意味着重启不会加载新内核。所以现在我们通过配置 libvirt 来解决这个问题，从而在重启时停止虚拟机。由于我们通常只在升级内核（安装）时重启 VM，虽然这有点乏味，但这避免了重启加载的是旧内核 / <code>initramfs</code> 而不是预期的。</p><hr>`,15)),i("p",null,[n[19]||(n[19]=s("via: ",-1)),t(a,{href:"https://www.collabora.com/news-and-blog/blog/2017/06/20/debian-armhf-vm-on-arm64-server/"},{default:e(()=>[...n[18]||(n[18]=[s("https://www.collabora.com/news-and-blog/blog/2017/06/20/debian-armhf-vm-on-arm64-server/",-1)])]),_:1})]),i("p",null,[n[23]||(n[23]=s("作者：",-1)),t(a,{href:"https://www.collabora.com/news-and-blog/blog/2017/06/20/debian-armhf-vm-on-arm64-server/"},{default:e(()=>[...n[20]||(n[20]=[s("Sjoerd Simons",-1)])]),_:1}),n[24]||(n[24]=s(" 译者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[21]||(n[21]=[s("geekpi",-1)])]),_:1}),n[25]||(n[25]=s(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[22]||(n[22]=[s("wxy",-1)])]),_:1})]),i("p",null,[n[28]||(n[28]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[26]||(n[26]=[s("LCTT",-1)])]),_:1}),n[29]||(n[29]=s(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...n[27]||(n[27]=[s("Linux中国",-1)])]),_:1}),n[30]||(n[30]=s(" 荣誉推出",-1))])])}const x=o(m,[["render",b]]);export{D as __pageData,x as default};
